@SpringBootTest(properties={"app.messaging.enabled=false","spring.kafka.admin.auto-create=false","app.issuance-delay-ms=3600000","app.data-encryption-key=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="}) @AutoConfigureMockMvc @Testcontainers
class TicketIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withInitScript("init.sql");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired IssuanceService issuance;@Autowired TicketQueries tickets;@Autowired AdmissionService admission;@Autowired EventGates gates;@Autowired TicketDocuments documents;@Autowired TicketPdfRenderer renderer;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired MockMvc mvc;
 @MockitoBean SourceClient source;@MockitoBean IdentityClient identity;@MockitoBean TicketArtifactStore store;@MockitoBean JwtDecoder decoder;
 final UUID owner=UUID.randomUUID(),staff=UUID.randomUUID(),organization=UUID.randomUUID(),eventId=UUID.randomUUID();Event event;Order order;
 @BeforeEach void fixture(){event=new Event(eventId,organization,"Hòa nhạc thử nghiệm","PUBLISHED","Nhà hát","Hà Nội","Asia/Ho_Chi_Minh",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200),false);order=new Order(UUID.randomUUID(),owner,eventId,organization,event.name(),"CONFIRMED","PUBLISHED",List.of(new Item(UUID.randomUUID(),UUID.randomUUID(),"Tiêu chuẩn",2)));when(source.event(eventId)).thenReturn(event);when(source.order(order.id())).thenReturn(order);when(source.contact(owner)).thenReturn(new Contact(owner,"fixture@example.test","Nguyễn An"));when(identity.securityState(any())).thenAnswer(a->new IdentityClient.SecurityState(a.getArgument(0),"ACTIVE",true,Set.of("CHECK_IN_STAFF")));when(source.assigned(staff)).thenReturn(List.of(eventId));}
 String fact(Order o,UUID message)throws Exception{return json.writeValueAsString(Map.of("eventId",message,"producer","event-commerce","eventType","order.confirmed","eventVersion",1,"payload",o));}
 void issue()throws Exception{issuance.accept(fact(order,UUID.randomUUID()));issuance.fulfill(order.id());}
 Ticket ticket(){return tickets.list(owner,order.id(),null,20).data().getFirst();}
 String credential(UUID id)throws Exception{String image=tickets.detail(id,owner).qrImage();var pixels=ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(image.substring(image.indexOf(',')+1))));return new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new BufferedImageLuminanceSource(pixels)))).getText();}
 String key(){return UUID.randomUUID().toString();}
 @Test void confirmedUnitsIssueExactlyOnceWithOpaqueStableQr()throws Exception{String body=fact(order,UUID.randomUUID());issuance.accept(body);issuance.accept(body);issuance.fulfill(order.id());issuance.accept(fact(order,UUID.randomUUID()));issuance.fulfill(order.id());var p=tickets.progress(order.id(),owner);assertThat(p.status()).isEqualTo("READY");assertThat(p.issuedCount()).isEqualTo(2);assertThat(p.tickets()).allMatch(t->t.qrImage()==null);String raw=credential(ticket().id());assertThat(raw).startsWith("ETP1.").hasSize(48).doesNotContain("Nguyễn","fixture",order.id().toString());assertThat(credential(ticket().id())).isEqualTo(raw);assertThat(db.queryForObject("select count(*) from ticket_admission.outbox where topic='ticket.ticket.issued.v1' and aggregate_id in (select id from ticket_admission.tickets where order_id=?)",Integer.class,order.id())).isEqualTo(2);assertThat(db.queryForObject("select string_agg(body::text,'') from ticket_admission.outbox where aggregate_id=?",String.class,ticket().id())).doesNotContain(raw);}
 @Test void unconfirmedAndChangedUnitFactsFailWithNoInboxEffect()throws Exception{Order bad=new Order(order.id(),owner,eventId,organization,event.name(),"PENDING_PAYMENT","PUBLISHED",order.items());assertThatThrownBy(()->issuance.accept(fact(bad,UUID.randomUUID()))).hasMessageContaining("ETK-R01");issuance.accept(fact(order,UUID.randomUUID()));Order changed=new Order(order.id(),owner,eventId,organization,event.name(),"CONFIRMED","PUBLISHED",List.of(new Item(order.items().getFirst().id(),order.items().getFirst().ticketTypeId(),"Tiêu chuẩn",3)));assertThatThrownBy(()->issuance.accept(fact(changed,UUID.randomUUID()))).hasMessageContaining("ETK-R02");assertThat(tickets.list(owner,order.id(),null,20).data()).isEmpty();}
 @Test void failedIssuanceRetainsObligationAndRetryFinishes()throws Exception{issuance.accept(fact(order,UUID.randomUUID()));when(source.contact(owner)).thenThrow(new IllegalStateException("offline"));assertThatThrownBy(()->issuance.fulfill(order.id())).hasMessage("offline");assertThat(tickets.progress(order.id(),owner).status()).isEqualTo("ISSUING");assertThat(db.queryForObject("select count(*) from ticket_admission.tickets where order_id=?",Integer.class,order.id())).isZero();doReturn(new Contact(owner,"fixture@example.test","Nguyễn An")).when(source).contact(owner);issuance.fulfill(order.id());assertThat(tickets.progress(order.id(),owner).issuedCount()).isEqualTo(2);}
 @Test void ownerOnlyDetailPdfAndProgress()throws Exception{issue();UUID id=ticket().id();assertThatThrownBy(()->tickets.detail(id,staff)).isInstanceOf(ApiException.class);assertThatThrownBy(()->documents.pdf(id,staff)).isInstanceOf(ApiException.class);assertThatThrownBy(()->tickets.progress(order.id(),staff)).isInstanceOf(ApiException.class);mvc.perform(get("/api/v1/tickets/"+id).with(jwt().jwt(j->j.subject(owner.toString())))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","private, no-store"));mvc.perform(get("/api/v1/tickets/"+id).with(jwt().jwt(j->j.subject(staff.toString())))).andExpect(status().isNotFound());}
 @Test void simultaneousScansYieldOneFreshAdmissionAndStatsCountOnce()throws Exception{issue();String raw=credential(ticket().id());var outcomes=race(()->admission.scan(eventId,staff,key(),raw).outcome(),()->admission.scan(eventId,UUID.randomUUID(),key(),raw).outcome());assertThat(outcomes).containsExactlyInAnyOrder("SUCCESS","ALREADY_USED");assertThat(admission.stats(eventId,staff).checkedIn()).isEqualTo(1);assertThat(admission.history(eventId,staff,null,20).data()).hasSize(1);}
 @Test void requestReplayIsExplicitAndChangedPayloadConflicts()throws Exception{issue();String raw=credential(ticket().id()),key=key();var first=admission.scan(eventId,staff,key,raw);var replay=admission.scan(eventId,staff,key,raw);assertThat(first.replayed()).isFalse();assertThat(replay.replayed()).isTrue();assertThat(replay.checkedInAt()).isEqualTo(first.checkedInAt());assertThatThrownBy(()->admission.scan(eventId,staff,key,"another")).isInstanceOf(ApiException.class).extracting(e->((ApiException)e).getCode()).isEqualTo("IDEMPOTENCY_CONFLICT");}
 @Test void lookupDoesNotConsumeAndManualConfirmationUsesSameGuard()throws Exception{issue();UUID id=ticket().id();assertThat(admission.lookup(eventId,staff,id).canCheckIn()).isTrue();assertThat(admission.stats(eventId,staff).checkedIn()).isZero();assertThat(admission.manual(eventId,staff,key(),id).outcome()).isEqualTo("SUCCESS");assertThat(admission.lookup(eventId,staff,id).canCheckIn()).isFalse();assertThat(admission.manual(eventId,staff,key(),id).outcome()).isEqualTo("ALREADY_USED");}
 @Test void wrongEventAndInvalidQrDoNotExposeTicketOrAdmit()throws Exception{issue();UUID other=UUID.randomUUID();when(source.event(other)).thenReturn(new Event(other,organization,"Other","PUBLISHED","Venue","Address","Asia/Ho_Chi_Minh",event.startAt(),event.endAt(),false));var wrong=admission.scan(other,staff,key(),credential(ticket().id()));assertThat(wrong.outcome()).isEqualTo("WRONG_EVENT");assertThat(wrong.ticketId()).isNull();assertThat(admission.scan(eventId,staff,key(),"invalid").outcome()).isEqualTo("INVALID_TICKET");assertThat(admission.stats(eventId,staff).checkedIn()).isZero();}
 @Test void outsideWindowDoesNotAdmitAndDenialReplayDoesNotTurnSuccess()throws Exception{issue();String raw=credential(ticket().id()),key=key();when(source.event(eventId)).thenReturn(new Event(eventId,organization,event.name(),"PUBLISHED","Venue","Address",event.timezone(),Instant.now().plusSeconds(7205),event.endAt().plusSeconds(8000),false));assertThat(admission.scan(eventId,staff,key,raw).outcome()).isEqualTo("OUTSIDE_CHECK_IN_WINDOW");when(source.event(eventId)).thenReturn(event);assertThat(admission.scan(eventId,staff,key,raw).outcome()).isEqualTo("OUTSIDE_CHECK_IN_WINDOW");assertThat(admission.scan(eventId,staff,key(),raw).outcome()).isEqualTo("SUCCESS");}
 @Test void frozenEventCannotIssueUsableTickets()throws Exception{gates.freeze(eventId);issuance.accept(fact(order,UUID.randomUUID()));issuance.fulfill(order.id());assertThat(tickets.progress(order.id(),owner).status()).isEqualTo("CANCELLED");assertThat(tickets.list(owner,order.id(),null,20).data()).isEmpty();issuance.fulfill(order.id());assertThat(db.queryForObject("select count(*) from ticket_admission.outbox where topic='ticket.order.cancelled.v1' and aggregate_id=?",Integer.class,order.id())).isEqualTo(1);}
 @Test void cancellationVoidsUnusedButPreservesUsedHistoryAndRemovesQr()throws Exception{issue();var list=tickets.list(owner,order.id(),null,20).data();String old=credential(list.getLast().id());admission.manual(eventId,staff,key(),list.getFirst().id());gates.freeze(eventId);gates.freeze(eventId);assertThat(tickets.detail(list.getFirst().id(),owner).status()).isEqualTo("CHECKED_IN");assertThat(tickets.detail(list.getLast().id(),owner).status()).isEqualTo("VOIDED");assertThat(tickets.detail(list.getLast().id(),owner).qrImage()).isNull();assertThat(admission.scan(eventId,staff,key(),old).outcome()).isEqualTo("EVENT_CANCELLED");assertThat(admission.stats(eventId,staff).eligible()).isZero();assertThat(admission.stats(eventId,staff).checkedIn()).isEqualTo(1);}
 @Test void cancellationAndScanRaceCannotCreateAdmissionAfterFence()throws Exception{issue();String raw=credential(ticket().id());var outcomes=race(()->{gates.freeze(eventId);return "FROZEN";},()->admission.scan(eventId,staff,key(),raw).outcome());assertThat(outcomes).contains("FROZEN");assertThat(outcomes.get(1)).isIn("SUCCESS","EVENT_CANCELLED");assertThat(admission.scan(eventId,staff,key(),raw).outcome()).isEqualTo("EVENT_CANCELLED");}
 @Test void cancellationAndIssuanceRaceLeavesNoUsableTicket()throws Exception{issuance.accept(fact(order,UUID.randomUUID()));race(()->{gates.freeze(eventId);return "FROZEN";},()->{issuance.fulfill(order.id());return "DONE";});assertThat(db.queryForObject("select count(*) from ticket_admission.tickets where event_id=? and status='ISSUED'",Integer.class,eventId)).isZero();}
 @Test void concurrentIssuancePreservesUnitUniqueness()throws Exception{issuance.accept(fact(order,UUID.randomUUID()));race(()->{issuance.fulfill(order.id());return "DONE";},()->{issuance.fulfill(order.id());return "DONE";});assertThat(tickets.progress(order.id(),owner).issuedCount()).isEqualTo(2);}
 @Test void revokedPermissionAndUnverifiedAccountFailBeforeReadingTicket()throws Exception{issue();doThrow(new ApiException(org.springframework.http.HttpStatus.FORBIDDEN,"FORBIDDEN","revoked")).when(source).authorize(eventId,staff);assertThatThrownBy(()->admission.lookup(eventId,staff,ticket().id())).hasMessage("revoked");assertThatThrownBy(()->admission.manual(eventId,staff,key(),ticket().id())).hasMessage("revoked");reset(source);when(identity.securityState(staff)).thenReturn(new IdentityClient.SecurityState(staff,"ACTIVE",false,Set.of("CHECK_IN_STAFF")));assertThatThrownBy(()->admission.stats(eventId,staff)).isInstanceOf(ApiException.class);}
 @Test void pdfContainsVietnameseIdentityAndUsedPdfHasNoQr()throws Exception{issue();UUID id=ticket().id();byte[] pdf=documents.pdf(id,owner);try(var doc=org.apache.pdfbox.Loader.loadPDF(pdf)){String text=new org.apache.pdfbox.text.PDFTextStripper().getText(doc);assertThat(text).contains("Nguyễn An","Hòa nhạc",id.toString());assertThat(images(doc)).isEqualTo(1);}admission.manual(eventId,staff,key(),id);try(var doc=org.apache.pdfbox.Loader.loadPDF(documents.pdf(id,owner))){assertThat(new org.apache.pdfbox.text.PDFTextStripper().getText(doc)).contains("ĐÃ CHECK-IN");assertThat(images(doc)).isZero();}}
 @Test void artifactFailureDoesNotReissueOrChangeOrder()throws Exception{issue();doThrow(new IllegalStateException("storage offline")).when(store).put(anyString(),any());assertThatThrownBy(()->documents.pdf(ticket().id(),owner)).isInstanceOf(ApiException.class);assertThat(tickets.progress(order.id(),owner).issuedCount()).isEqualTo(2);}
 @Test void publicCannotFreezeAndMalformedScanIsRejected()throws Exception{mvc.perform(post("/internal/admission/events/"+eventId+"/freeze").header("X-Service-Token","wrong")).andExpect(status().isForbidden());mvc.perform(post("/api/v1/check-in/events/"+eventId+"/scan").with(jwt().jwt(j->j.subject(staff.toString()))).header("Idempotency-Key",key()).contentType("application/json").content("{}" )).andExpect(status().isBadRequest());}
 @Test void ticketListPaginationHasNoForeignOrRepeatedUnits()throws Exception{issue();var first=tickets.list(owner,order.id(),null,1);assertThat(first.hasMore()).isTrue();var last=tickets.list(owner,order.id(),UUID.fromString(first.nextCursor()),1);assertThat(last.data().getFirst().id()).isNotEqualTo(first.data().getFirst().id());assertThat(last.hasMore()).isFalse();assertThat(tickets.list(staff,null,null,20).data()).isEmpty();}
 int images(org.apache.pdfbox.pdmodel.PDDocument doc)throws Exception{int count=0;for(var name:doc.getPage(0).getResources().getXObjectNames())if(doc.getPage(0).getResources().getXObject(name) instanceof org.apache.pdfbox.pdmodel.graphics.image.PDImageXObject)count++;return count;}
 List<String> race(Callable<String> a,Callable<String>b)throws Exception{var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var x=pool.submit(()->{start.await();return a.call();});var y=pool.submit(()->{start.await();return b.call();});start.countDown();return List.of(x.get(15,TimeUnit.SECONDS),y.get(15,TimeUnit.SECONDS));}}

 @Autowired com.eventticketing.admission.api.ReminderEligibilityController reminder;
 @Test void reminderRequiresIssuedNonVoidedTicketAndAnOpenEventGate()throws Exception{assertThat(reminder.check(eventId,owner,"local-service-token").get("eligible")).isEqualTo(false);issue();assertThat(reminder.check(eventId,owner,"local-service-token").get("eligible")).isEqualTo(true);assertThat(reminder.check(eventId,UUID.randomUUID(),"local-service-token").get("eligible")).isEqualTo(false);db.update("update ticket_admission.tickets set status='VOIDED' where event_id=?",eventId);assertThat(reminder.check(eventId,owner,"local-service-token").get("eligible")).isEqualTo(false);gates.freeze(eventId);assertThat(reminder.check(eventId,owner,"local-service-token").get("eligible")).isEqualTo(false);}
}
